{"tool":"newFileCreated","path":"src/main/java/set/starlev/injections/mixin/render/entity/BearSpiritNameTagMixin.java","content":"package set.starlev.injections.mixin.render.entity;

import net.minecraft.client.renderer.entity.LivingEntityRenderer;
import net.minecraft.client.renderer.entity.state.LivingEntityRenderState;
import net.minecraft.world.entity.LivingEntity;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
import set.starlev.StarredHeltix;
import set.starlev.utils.detectors.DungeonDetector;

/**
 * Скрывает vanilla name tag для моба "Дух медведя", чтобы избежать двоения
 * с нашим кастомным renderText из Floor4.
 */
@Mixin(LivingEntityRenderer.class)
public abstract class BearSpiritNameTagMixin {

    @Inject(method = "extractRenderState", at = @At("RETURN"))
    private void onExtractRenderState(LivingEntity entity, LivingEntityRenderState state, float partialTick, CallbackInfo ci) {
        // Проверяем, активна ли функция подсветки Духа медведя
        try {
            if (!DungeonDetector.isInDungeon()) return;
            if (!StarredHeltix.INSTANCE.getFeature().getDungeons().getFloor4().getBearSpiritHighlight()) return;
            if (!StarredHeltix.INSTANCE.getFeature().getDungeons().getFloor4().getBearSpiritText()) return;

            // Проверяем имя моба
            var customName = entity.getCustomName();
            if (customName != null && customName.getString().contains("Дух медведя")) {
                // Скрываем vanilla name tag, чтобы не двоился с нашим кастомным
                state.nameTagComponent = null;
            }
        } catch (Exception ignored) {
            // Игнорируем ошибки, чтобы не ломать рендер
        }
    }
